def analyze_pattern(inputs, outputs):
    """Analyze what characters need to be replaced"""
    # Create mapping from input to output characters at each position
    replacements = {}

    # For each pair of input/output strings
    for inp, out in zip(inputs, outputs):
        # Compare character by character
        min_len = min(len(inp), len(out))
        for i in range(min_len):
            if inp[i] != out[i]:
                if inp[i] not in replacements:
                    replacements[inp[i]] = out[i]
                elif replacements[inp[i]] != out[i]:
                    # Conflict - need to handle carefully
                    pass

    return replacements

inputs = ['chd', 'ahxwy', 'hy', 'vyk', 'ik']
outputs = ['uxd', 'acxwy', 'cy', 'vyij', 'iij']

replacements = analyze_pattern(inputs, outputs)
print("Character mappings:", replacements)

